layers.vertex:
attribute vec3 aO; attribute float aT, aK, aA; uniform float uTime; uniform vec3 uAlly; varying vec2 vP; varying float vU, vK;
    void main(){ float u = uTime - aT; if (u < 0. || u > (aK < .5 ? 0.700 : 1.000)){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vec3 O = aA > .5 ? uAlly : aO;
      vU = u; vK = aK; vP = position.xy;
      if (aK < .5){ float S = .95; vP = position.xy*S; gl_Position = projectionMatrix*viewMatrix*vec4(O + vec3(position.x*S, .03, -position.y*S), 1.); }
      else { vec3 f = cameraPosition - O; f.y = 0.; f = normalize(f); vec3 rt = vec3(f.z, 0., -f.x);
        vP = vec2(position.x*.7, (position.y*.5 + .5)*2.5);                 /* metres: x across, y up from the feet */
        gl_Position = projectionMatrix*viewMatrix*vec4(O + rt*vP.x + vec3(0., vP.y, 0.), 1.); }
    }

layers.fragment:
uniform vec3 uGold, uOrange; varying vec2 vP; varying float vU, vK; float lcore(float d, float w){ return exp(-(d*d)/(w*w)); }
    float h1(float n){ return fract(sin(n*91.7)*43758.5); }
    void main(){
      float lum = 0., hot = 0.;
      if (vK < .5){
        float t = vU/0.700, r = length(vP), e = 1. - pow(1. - clamp(vU/.35, 0., 1.), 3.), R = .2 + .55*e, f = .7*(1. - smoothstep(.5, 1., t));
        lum += exp(-pow(abs(r - R)/.014, 2.4))*f; hot += lcore(r - R, .005)*f*.5;
        lum *= smoothstep(.95, .85, r); hot *= smoothstep(.95, .85, r);
      } else {
        // tiny 4-point stars fall from the head (2.25 m), spreading a little as they drop, twinkling, gone before the feet
        for (int i=0;i<16;i++){
          float fi = float(i), d = h1(fi)*.35, t = vU - d;
          if (t < 0. || t > .65) continue;
          float x0 = (h1(fi + 3.) - .5)*.3, x = x0*(1. + t*2.2) + (h1(fi + 7.) - .5)*.25*t;
          float y = 2.2 - (1.1*t + 2.*t*t), sz = .065 + .035*h1(fi + 11.);
          vec2 q = vP - vec2(x, y); float r = length(q), a = atan(q.y, q.x);
          float tw = .65 + .35*sin(vU*30. + fi*2.3), life = sin(3.14159*clamp(t/.65, 0., 1.));
          float st = pow(abs(cos(a*2.)), 14.)*exp(-r/sz*1.6) + exp(-r*r/(sz*sz*.08));
          lum += st*tw*life*1.4; hot += 1.3*exp(-r*r/(sz*sz*.03))*tw*life;
        }
        lum *= smoothstep(.1, .5, vP.y)*smoothstep(.7, .55, abs(vP.x)); hot *= smoothstep(.1, .5, vP.y)*smoothstep(.7, .55, abs(vP.x));
      }
      vec3 o = uOrange*lum + mix(uGold, vec3(1.), .5)*hot;
      if (max(o.r, max(o.g, o.b)) < .002) discard;
      gl_FragColor = vec4(o, 1.);
    }
